import {castSceneV74} from './cast-scenes-v74.js';
const rows=[
 ["name-ping","Wine，還是 Wing？","群組一聲Wine，整排同事先坐正。紅酒走過來問哪台主機有問題，發現大家剛才正把玩具鵝藏到桌下。","差一個字母，我沒有突然多一間辦公室。","回覆人名與系統名稱。","紅酒接到真正的問題，大家也把藏一半的鵝放回來。","先喊老闆好，再看看來的是誰。","紅酒被你喊到停下，問自己是不是又多了一份不用加薪的兼任。","替兩個名字加交通號誌：紅酒綠燈，翅膀紅燈。","你畫好號誌，紅酒先要求不要把他設成全天候綠燈。","幹，人名看清楚再喊。差一個字母不是同一個人，別連職權跟工作一起轉錯。","靠北，別又把紅酒當老闆叫，叫完還要他負責老闆的答案。"],
 ["reply-all","回信最有權力的一次，因為收件人認錯。","客戶看到Wine的署名，寄來一整串要拍板的價格。紅酒盯著折扣表，說自己會調的是連線，不是公司的毛利。","我可以查主機，這個折扣你找錯控制台了。","指出角色，轉回正式報價窗口。","紅酒把價格權限退回原處，沒有順便承諾免費維護。","幫忙回個大概，先讓客戶安心。","一句大概被轉寄三次，最後只剩下公司同意。紅酒又收到一份需要拆彈的信。","把報價信轉成主機錯誤：權限不足，請洽真正老闆。","你寫了錯誤畫面草稿，紅酒笑完改成正常轉介。至少這次沒有用管理員帳號替公司打折。","幹，工程信箱不是報價櫃台。先問有沒有權限，別把一封寄錯的信變成免費服務。","靠北，後面議價別再副本紅酒就當他答應，他沒賣過自己的晚上。",["sales","bd","system"]],
 ["let-crash","新主管問系統怎樣，紅酒說：讓它爆。","老大第一次問系統現況，紅酒看著滿頁警報，回了一句讓它爆。停了兩秒，他把最常炸的三處打開，原來這句話還附完整的爆點導覽。","真讓它爆，半夜接電話的還是我。","把爆點改成能處理的風險清單。","紅酒講完前因後果，老大先安排能止血的一項，沒有要求你們今晚重造公司。","只記錄讓它爆，拿去當會議結論。","會議紀錄很短，下一次警報很長。紅酒問你怎麼把解法全部省略了。","替每個爆點放一隻紙鵝，舉辦首次機房賞鵝團。","紙鵝沿著故障路線排滿，老大倒是第一次看懂哪幾處不能一起動。","幹，後面三個風險一起講，不要只剩「讓它爆」傳來傳去。工程問題不會靠一句氣話就自己處理。","靠北，要修哪個先講，不要下次又把紅酒那句話當成放著不管的授權。",["system","mis","ai","executive"],"server_room",{"participants":["wine","henry"]}],
 ["last-resort","紅酒會修，所以全部都歸紅酒。","資料庫、網路與測試機各出一件事，三張單都被轉給紅酒。轉單理由只有他比較懂，你看這四個字正在長出第四張單。","比較懂，不代表同時有四雙手。","先排嚴重程度，另找一位接手。","紅酒救最急的一件，你接下能處理的部分；三張單終於不再搶同一雙手。","說能者多勞，自己先處理別的。","紅酒忙到忘了午餐，你下午又多出一個等他回覆的卡點。","替比較懂申請一張分身產能許可證。","許可證上寫核發零位分身。紅酒把它貼在三張單前面，要求大家真的排先後。","幹，懂最多就要扛全部？同時三件先選順序，別把能力當成無限加班授權。","靠北，分工排了就照做。別再把自己那張偷偷轉回紅酒，還寫一句辛苦你了。",["system","ai","mis","project"]],
 ["late-light","下班燈關了，紅酒的螢幕還亮。","你回來拿雨傘，看見紅酒對著同一台機器。他說只差最後一步，螢幕旁的晚餐卻已經冷成一份歷史備份。","這一步從六點走到現在，路有點長。","一起確認阻塞點與明天的交接。","紅酒留下現況，終於能把晚餐帶走加熱。你沒有再答應今晚一定好。","幫他帶咖啡，鼓勵再撐一輪。","咖啡熱了，晚餐更冷。你們醒著的時間增加，真正卡住的權限仍沒來。","替最後一步鋪紅毯，要求它走完不得再加安可。","紅酒笑著寫下終止條件。紅毯只是一條便條紙，卻把今晚停在哪裡畫了出來。","幹，最後一步都喊三小時了。卡的是權限就講權限，別把熬夜當成解法。","靠北，今晚不能再把新問題包進最後一步，讓人永遠走不到門口。",["system","ai","mis"]],
 ["pager-name","待命表寫紅酒，大家都覺得自己被放假。","新待命表只填紅酒，備援欄寫必要時支援。你問必要時誰先接，群組忽然安靜得像所有人都已經在山上。","名字有寫跟願意幫忙，是兩種排班。","補上主備與交接時段。","紅酒看到能真的輪替的人名，第一次敢在下班前把手機靜音十分鐘。","先照舊，真的出事再揪大家。","出事時每個人都剛好沒看到。紅酒又接完一輪，表格則保持非常有彈性。","讓必要時本人來報到，先替它辦一張門禁卡。","你替空白欄畫了一張卡，紅酒在卡上補了真正的備援人。虛構員工正式失業。","幹，必要時是哪位同事？值班表填人跟時段，別只把紅酒的電話寫成公司保險。","靠北，下一通照順序接，不要每次都說紅酒最熟，就把輪班當裝飾。",["system","mis","hr","admin"]],
 ["coffee-ticket","紅酒說喝一口，工單自己坐了過來。","紅酒端著飲料坐下，旁邊的人立刻問能不能順便看一下。吸管還沒拆，螢幕已經被推到他的杯子前面。","我現在要解的是口渴，不是你這台。","讓他先喝完，再把問題放進工單。","紅酒總算喝到第一口，你的問題也有了能追的編號。","趁他人在，先把整台筆電擺過去。","紅酒接了機器，飲料一路放到退冰。你得到協助，也得到一個很不想再看你筆電的表情。","替飲料開最高優先工單：五分鐘內完成飲用。","紅酒先簽收飲料，請你排在冰塊後面。這次最高優先至少真的很快結案。","幹，連喝口水都要順便維修？問題排工單，別拿人剛坐下當成免費叫號。","靠北，午休就讓人吃飯喝水，不要靠先把電腦推過去取得優先權。"],
 ["error-photo","錯誤截圖只有紅色，其他全被裁掉。","你拿一張紅色訊息請紅酒看，時間、路徑與程式名稱都不見了。紅酒盯了五秒，問這是系統出錯，還是有人傳了色票。","這張我能判斷的只有它真的很紅。","補完整畫面與發生步驟。","紅酒找到能重現的問題，今天不用先從截圖猜是哪個系統。","再拍近一點，讓紅字更大。","紅字占滿整頁，資訊仍然很少。紅酒建議你把印表機也調成同一個色號。","把紅色訊息送去評圖，請翅膀選第一版。","紅酒笑到先把手機放下，提醒你評圖前還是得補時間戳。","幹，裁到只剩紅色是要通靈？系統名、時間、怎麼操作都給，紅酒不是錯誤色卡辨識員。","靠北，重現步驟有了就留著。下次不要只傳最醒目的那一塊，又從猜機器開始。",["system","ai","mis","design"]],
 ["sam-clock","紅酒的工時表，遇上山姆的進度條。","紅酒要整理離開前的工作，山姆那一欄卻一直寫處理中。你們只核對交付紀錄，發現同一件工作已經跨過三次週會。","我想問的是交了什麼，不是誰看起來比較忙。","逐件列出交付、卡點與負責人。","紅酒把可核對的差異留在表上，沒有用辦公室傳聞補空白。","幫忙寫大家都很忙，先別細分。","表格看起來很團結，原本那些待辦也團結地回到紅酒身上。","替處理中辦長住證，租金按未交付的週數計算。","山姆看著長住證笑不太出來，紅酒則把笑話旁邊的實際日期填完。","幹，問交付不是辦比慘大會。哪件做了、哪件沒做講清楚，別再拿大家很忙把差別洗掉。","靠北，後面談工作就拿日期跟成果，不要把誰坐多久當成完成證明。",["system","ai","project","executive"],"office_day",{"participants":["wine","sam"]}],
 ["handover-holiday","交接清單最長的一欄：大家以為他會。","紅酒把接手事項打開，裡面混著從來沒正式交給他的帳號與雜事。你每往下滑一頁，就多認識一種大家以為工程師本來就該會的工作。","會做跟一直由我做，最好在交接前分清楚。","分出正式工作、臨時支援與需要另找人的部分。","接手的人拿到真的範圍，紅酒不用把整間公司裝進離職文件。","全部打包給下一位能者。","新人的第一封信問是不是錄取了五個職缺，你忽然懂紅酒為什麼要離開。","把清單印成百科全書，封面寫一人份部門史。","紅酒補了一頁如何不要再長成這本書，要求各窗口正式認領。","幹，交接不是把所有沒人要的工作黏成一本。哪個窗口負責就寫誰，別找下一位紅酒來重演。","靠北，臨時幫忙也留紀錄，別三個月後又變成他本來就負責。",["system","mis","hr","admin"]],
 ["restart-order","重開機之前，先救還沒存的東西。","有人把重開試試當成萬用解法，紅酒卻先問哪個程序還在跑。你看螢幕上的匯入只剩一點，滑鼠已經停在重新啟動上。","先知道會丟什麼，再決定要不要重開。","保存資料並確認能中斷的服務。","紅酒等到匯入完成，重啟後沒有多出一份需要補回的下午。","先按，反正重開最快。","速度確實很快，從百分之九十九回到零只花一秒。紅酒把重新匯入排進待辦。","替重開鍵加一道口試：請說明你準備重做哪些事。","紅酒借你的紙蓋住按鈕，旁邊的人終於願意先看狀態。","幹，最快是畫面黑掉，不是工作好了。還在跑什麼先看，別用重開把別人的下午歸零。","靠北，停機條件寫了就照做。不要看見慢就直接按，讓重啟變成每日固定災情。",["system","mis","ai"]],
 ["boss-answer","問紅酒一個技術問題，回來一個老闆答案。","你請紅酒估工，群組卻有人轉述成Wine說老闆答應了。紅酒看到自己原話只剩三個數字，旁邊多出一個他沒有核准過的日期。","我估的是時間，沒有順便發聖旨。","貼回估算前提，請拍板者確認。","紅酒的名字回到技術估算欄，決策終於找到真正有權力的人。","日期先接下來，等做到再解釋。","期限開始被倒數，原本的前提則被說成你們怎麼現在才提。","替每份估算加水印：本酒不具行政效力。","紅酒笑著把水印縮成前提欄，這次沒人能只截最後一行。","幹，估工不是答應交期。前提一起轉，別借一個像老闆的名字替全組人簽約。","靠北，引用紅酒把整句帶上，不要每次只留下最方便催人的數字。",["system","project","sales","bd"]],
 ["one-more-port","多開一個連接埠，被講得像多開一扇窗。","紅酒收到一句只是開個port，後面沒有用途、來源或關閉時間。對方說先弄，demo快到了；紅酒問demo結束後誰會記得那扇窗。","開門前總得知道誰要進來。","補用途與期限，限定需要的範圍。","紅酒只開必要的入口，活動後也有負責關掉的人。","先全開，demo過了再說。","demo順利，開口卻留了下來。紅酒隔週又被問為什麼系統有這個設定。","替連接埠掛上門房牌，來賓先填入住與退房時間。","你畫完旅館登記卡，對方總算肯寫明測試何時結束。","幹，開個port也要有用途跟期限。不要一句先弄，就把沒人認領的門永遠留給紅酒守。","靠北，結束就照表收回，別讓臨時設定活得比專案本人還久。",["system","mis","ai"]],
 ["deploy-window","部署時段寫晚上，所以白天還能再塞滿。","紅酒的排程上，白天開會、晚上部署。有人說晚上才不會影響客戶，你問那做事的人要在哪個時段不受影響。","晚上做，不代表白天的工時就不用算。","安排調整班次與部署前休息。","紅酒保住一段完整休息，晚上沒有靠第三杯咖啡檢查重要設定。","先把白天排完，晚上再見。","紅酒在部署前開始看錯行，大家才同意那個晚上不是額外長出來的。","替月亮送人力申請，請它派一位晚上版紅酒。","月亮沒有回信，時程表倒真的挪出白天的空檔。","幹，晚上維護就排晚上工時。白天全塞滿還要半夜清醒，是把紅酒當兩班輪替的同一個人？","靠北，後面要補會議先重算，不要只借回白天，假裝晚上還有另一份體力。",["system","mis","project","hr"]],
 ["runbook-map","文件一打開，第一步是先問紅酒。","你翻到一份操作手冊，前三步都寫找紅酒確認。紅酒說這不是runbook，是一張把他召回現場的三段咒語。","我不在線的時候，這本書才真的需要有用。","請他示範一次，記下實際判斷與停點。","你補出能操作的步驟，手冊第一次比通訊錄多一點內容。","把紅酒的分機加粗，算作改善。","字變大了，沒人因此會處理。紅酒休假時，你還是守著那串粗體。","替手冊附一頂召喚帽，召喚失敗就強制補文件。","紅酒把帽子戴在玩具鵝上，讓鵝守著你把步驟寫完。","幹，每一步都找紅酒，那叫通訊錄。文件是人不在也能看，別把請教寫成永久依賴。","靠北，步驟補了就真的試。下次不要自己跳回打電話，然後說文件從來都沒用。",["system","mis","ai","admin"]],
 ["test-account","測試帳號說隨便，最後連正式資料都看得到。","紅酒替demo準備帳號，需求卻是什麼都能看比較方便。你看著要展示的三個畫面，忽然不知道另外幾十頁是要表演給誰。","方便展示，不等於整台保險箱都借出去。","只留展示範圍，另用測試資料。","紅酒把帳號權限收在需要的地方，現場也少了一份不能外流的緊張。","先用最高權限，免得demo卡住。","demo沒卡，紅酒卻得一直盯著滑鼠，怕下一頁開到不該看的東西。","替帳號穿展示服，只准在畫好的伸展台走。","紅酒把你的伸展台改成權限清單，帳號總算不用全裸上陣。","幹，展示三頁就給三頁的權限。不要一句方便就開滿，再叫旁邊的人替每次點擊捏把冷汗。","靠北，活動結束就收，不要把今天的方便當成永久訪問證。",["system","mis","sales","bd"]],
 ["lunch-rescue","紅酒的便當，常常需要第二次報到。","微波爐響了，紅酒卻被叫去看一個臨時故障。你看便當從中午等到下午，飯盒上的貼紙比原主人更熟悉茶水間。","這個便當已經比我準時下班了。","接住能處理的詢問，讓他先吃完。","紅酒吃到熱飯，你也發現那件急事其實能等十分鐘。","幫忙把飯再冰回去，等他忙完。","飯盒回到冰箱，紅酒的午休則沒有回來。你們又多了一份放到隔餐的工作記憶。","替便當打卡出勤，要求公司補發兩次午休。","紅酒拿著便當的假工時表笑了一下，總算願意先把電話交出去。","幹，吃飯十分鐘都不能等？先分清真故障跟有人想插隊，別把紅酒的午休當緩衝區。","靠北，飯就讓人吃完，下一件不要又喊只有一分鐘把人叫走。"],
 ["holiday-blame","假日出問題，電話先找到了一個嫌疑人。","假日部署出狀況，山姆打來問紅酒是不是傑克動了什麼。紅酒沒接那個猜測，把旁邊的傑克叫來一起核對操作與紀錄；你看見電話另一頭的結論正在等事實追上。","先看哪一步出錯，不要先挑一個名字。","把操作紀錄與實際改動按時間排好。","你們找出真正卡點，討論不用先讓一位同事穿上嫌疑人的背心。","先跟著說可能是傑克，之後再看。","傑克問你看到哪一段紀錄，你才發現自己剛才只接到一通很有方向感的電話。","請錯誤訊息坐證人席，任何人名必須等它先作證。","紅酒把你的證人席畫在紀錄旁，玩笑歸玩笑，原因總算照實際改動往下查。","幹，出問題先查紀錄，不是先找一個人怪。電話講得再肯定，也不能代替實際操作。","靠北，後續就按時間線看，別又把某個人的名字放在原因前面，讓整場排查變成猜兇手。",["system","ai","project"],"office_day",{"participants":["wine","jack"]}],
 ["breakfast-trust","山姆說只信任你，早餐忽然附了一張組織圖。","山姆約紅酒聊早餐，說有一個小主管的位置可以談，還加了一句只信任你。紅酒看看對方畫的組織圖，先問職責、待遇和誰負責拍板，場面立刻比蛋餅還安靜。","被信任不錯，正式條件總不能只有這四個字。","把職責、待遇與決策程序問清楚。","紅酒留下要正式確認的項目，沒有在早餐桌上先簽收一整組未定的工作。","幫忙說這麼受信任就先答應。","紅酒問你待遇誰決定，你才發現那張組織圖連日期都沒有。","替只信任你估值，問它能折多少月薪與幾位下屬。","山姆把筆放下，紅酒笑著請他先把真的條件帶回去確認。","幹，只信任你不能當薪資條件。職責、待遇、誰拍板一次講，不要用一頓早餐替人升整組責任。","靠北，要談就拿正式條件來，別一直重播只信任你，讓人還沒升職就先不好意思拒絕。",["system","hr","executive"],"office_day",{"participants":["wine","sam"]}],
 ["no-meeting-demo","展示當天，紅酒被要求站在螢幕後面。","demo簡報沒有紅酒的名字，行前清單卻指定他全程在場。有人說只是備用，你看備用的位置連一張椅子都沒排。","要我隨時救火，至少先讓我知道會怎麼演。","把技術備援與演示腳本一起確認。","紅酒知道哪個畫面不能亂點，現場也有真正能坐的備援位置。","請他先待附近，出事再叫。","台上換到沒試過的頁面，第一聲紅酒比第一張產品圖還準時。","把紅酒畫進產品架構，標示唯一不能當備註的人形元件。","紅酒笑完要求把人形元件改成正式支援項目，還附一張椅子。","幹，說只是備用又整天不能走？技術支援先排時段跟內容，別把工程師當躲在布幕後面的插座。","靠北，腳本對好了就照走。臨場加戲先問，別拿台下那聲紅酒當萬用復原鍵。",["system","sales","bd","project"]],
 ["leave-bell","休假核准了，紅酒的電話還在值班表。","紅酒把核准假單貼進群組，窗口卻說有狀況還是找他最快。你看那張假單，忽然像一封獲准離開座位的遠端待命通知。","最快是讓我放不到假，不是讓問題消失。","移交當值窗口，說清楚可升級的條件。","紅酒的名字離開當日表格，休假終於不用靠收訊差來保護。","先把手機帶著，大家應該不會常問。","第一通問的是檔案放哪。紅酒在路邊翻起資料夾，景點因此新增一處公司共享磁碟。","給手機也發休假證，禁止它把風景轉成遠端桌面。","紅酒把假證當桌布，真的交出當值窗口後才收好手機。","幹，核准休假就找代理。不能每次都說紅酒最快，把人家的假放成訊息回覆馬拉松。","靠北，先看再問，別拿一通電話省自己的三十秒，吃掉別人的半天。",["system","mis","hr","admin"]],
 ["faster-hardware","要紅酒加快，設備卻還在思考去年。","翅膀問為什麼測試那麼慢，紅酒按下執行後請大家看進度條。機器轉了很久，風扇比任何人更努力回應這場會議。","我可以加快手，這台不接受精神喊話。","列出等待時間與可比較的升級方案。","紅酒把慢的位置量出來，討論終於能離開你要更快的那一句。","多催紅酒幾次，看看能不能擠出速度。","你們把催促回覆得很快，機器仍照自己的年紀跑。","替風扇頒最佳員工，請老闆先和它談績效。","風扇沒有上台，紅酒拿到一張真正能討論的設備清單。","幹，機器跑半小時是要工程師用嘴吹快？等待時間都在那裡，先談資源別先談態度。","靠北，選不升級就承認要等，不要省硬體錢還要求人用加班補算力。",["system","ai","mis"]],
 ["permission-late","權限下午才給，期限照早上算。","紅酒從早上等測試權限，下午收到開通，對方接著問今天能不能做完。你看看空白的上午，原來也能被算成他已經用過的工時。","等鑰匙的時間，門不會自己開。","重新確認可開始時間與交付範圍。","紅酒把起點對回實際開通，今天的工作終於不是從一扇鎖門開始追責。","照原期限答應，晚上追回來。","權限問題消失了，等待的成本卻順利搬進紅酒今晚的行事曆。","向門禁申請時光倒流，失敗就請期限往後挪。","門禁沒開放這項功能，你們只好正常更新時程。","幹，下午才給權限還按早上算？等待不是已經開工，別拿別人的晚上補你沒交出的鑰匙。","靠北，缺前置條件就一併改表，不要只通知開通，假裝前面那半天沒發生。",["system","ai","mis","project"]],
 ["quiet-victory","系統一整天沒叫，紅酒被問今天做了什麼。","警報安靜了一天，紅酒的週報反而被問是不是沒進度。你看見他前一天補的監控與備援，第一次覺得成果做得太成功也會隱形。","不要等它爆了，才承認維護算工作。","列出已完成的防護與驗證結果。","紅酒的安靜有了能對照的成果，週報不用硬加一場事故當證明。","寫系統正常就好，懂的人會懂。","對方回覆正常不是本來就該。紅酒把省下的故障時間又解釋了一輪。","替零警報舉辦無聲記者會，主持人全程不得叫紅酒。","你們安靜拍完一張空白投影，紅酒在旁邊補上真正的維護紀錄。","幹，沒出事不等於沒做事。維護成果先看，別非要炸一台給你看才肯算工時。","靠北，系統安靜先謝謝有人處理，不要把沒聽見警報當沒人在工作。",["system","mis","executive"]],
 ["overtime-ledger","紅酒把補休表打開，規則終於開始長字。","紅酒整理一整頁待處理的加班與補休紀錄，原本口頭說可以的事，忽然有人要求每一筆重新填申請。你看見表格越補越長，想知道先前照誰的說法做，現在該去問誰。","要補文件就一筆一筆核對，別把以前同意過的時間當沒發生。","對回出勤、指示與當時的確認紀錄。","紅酒把每筆資料接起來，窗口能逐項回覆，沒有只用一張新表把整頁舊時間蓋掉。","新表沒填就全部先算沒有，讓事情快點結案。","結案快得令人不安，紅酒問你那幾個晚上是不是也能一起當成沒發生。","替每個加班夜晚發門禁卡，排隊到新表前面問自己何時被批准消失。","你畫了整排夜晚的名牌，紅酒把笑話收好，繼續追能核對的正式回覆。","幹，新表可以補，舊時間不能直接抹掉。當時怎麼指示就怎麼對，別讓人加完班才考另一套規則。","靠北，逐筆回覆就逐筆講，別只丟一句以後照新規定，把以前那整頁都留給員工自己吞。",["system","hr","admin","executive"],"meeting"],
 ["captain-rsvp","船票寄到紅酒，行事曆先伸手擋住。","船長揪紅酒下班聚會，紅酒說今晚另有安排。有人起鬨能者多陪，你看他白天替系統備援，晚上居然也被要求替氣氛備援。","我今天不能去，真的只是在說今天不能去。","尊重回覆，另找有空的人。","船長改問其他人，紅酒把晚上的時間留在自己的行事曆。","幫忙說他應該可以晚點到。","紅酒問你怎麼知道他的晚上。你多答應的一句，變成兩邊都要再確認的麻煩。","替船票蓋已另有航線章，宣布今晚不接受改派。","船長笑著收好船票，紅酒要求那個章明天也借他擋臨時會。","幹，人家說沒空就沒空。下班不是第二張待命表，別替紅酒把晚上答應出去。","靠北，今晚的安排講清楚了。下次邀約問本人，不要拿旁邊一句應該可以當船票。",[],"office_day",{"participants":["wine","captain"]}],
 ["demo-scope","要穩定上線，還是要一切都先上線？","紅酒拿著部署清單問先做哪個，對方回答都要穩也都要快。你看清單裡兩個尚未驗證的功能，感覺這份需求正在表演同時踩油門煞車。","都要可以，但得把今天能驗證的範圍講清楚。","分成穩定版與後續項目。","紅酒先送出能驗證的部分，剩下兩項不再躲在快好了後面。","全部一起放，祈禱沒人點到新功能。","新功能第一個被點，大家開始用最慢的方式追回剛才省下的測試。","請願景先去測試環境過夜，明天再回正式站發表。","紅酒笑著替願景留好測試位置，兩個未驗項目也真的留了下來。","幹，穩定又快不是省掉驗證的口號。今天能上什麼先選，別把風險全塞進紅酒的電話。","靠北，新想法排下一輪，別到最後五分鐘又說順便一起上。",["system","ai","project","product"]],
 ["chair-maintenance","工位寫系統工程師，椅子卻像行動客服車。","紅酒才坐下就被另一排叫過去，你幫他推椅子，發現輪子比今天的伺服器還忙。他說連離開座位都不用記，反正沒坐熱過。","我能遠端看，不代表得每一台旁邊都親自站。","集中遠端資訊，把現場支援排一輪。","紅酒總算能坐完一次檢查，你也不用一路抱著電腦追他的椅子。","看到他路過就再叫一聲。","紅酒的路線多繞兩圈，你得到一個很短的稍後；整排人都在等那個稍後。","替椅子裝里程表，要求它領外勤津貼。","紅酒把玩笑畫成支援地圖，大家第一次看到今天究竟把他叫走幾次。","幹，椅子比主機還忙是怎樣？能遠端就給資料，別看人走過就把他當隨叫隨到的推車。","靠北，下一台照單走，別再用大聲一點取得比較前面的座位。"],
 ["goodnight-monitor","監控傳晚安，紅酒不敢相信。","紅酒替一串不重要的通知做了分級，晚上第一次只收到真的需要處理的警報。你們在下班前測試，發現手機安靜得令人有點不安。","安靜不是壞掉，是終於知道什麼不用現在吵。","核對重要警報仍能送到。","紅酒確認必要通知正常，其他訊息照約好的時間整理。今晚不用被每次心跳都叫醒。","把所有通知全打開，才有在監控的感覺。","手機回到熟悉的震動，真正重要的一則又混進一整排正常訊息。","替正常訊息辦退休餐會，餐費是今晚的一覺。","紅酒替它們準備一個安靜的日報資料夾，退休員工仍然按時交報表。","幹，監控不是比誰吵。重要的送到，正常的整理，別讓紅酒每晚替一堆沒事簽收。","靠北，要加通知先分級，不要把所有正常都重新升級成半夜急件。",["system","mis","ai"]],
 ["exit-report","紅酒交出的最後一份，是能核對的工作表。","有人問紅酒離開前要不要講真心話，他把工時與交付紀錄放上桌。那裡有支援、有等待，也有明明掛別人的名字卻一直由他補的缺口。","我講哪一項，就拿哪一項紀錄，不用替我加戲。","按紀錄反映分工與負荷。","紅酒把具體問題交到正式窗口，沒有讓一場去留變成辦公室猜人比賽。","替他補幾個大家聽過的傳聞。","紅酒把未確認的句子劃掉，請你別讓真正能講的工作問題一起變得站不住腳。","替每件補位工作安排畢業典禮，請原負責人親自領回。","紅酒沒有真的穿學士服，交接表卻終於有人願意簽名認領。","幹，工作表就在這裡，講紀錄就好。別加一堆沒核對的話，把真正不合理的分工也攪成八卦。","靠北，窗口已經收件。後續按項目追，不要又改成聽說誰怎樣，讓能處理的事全部失焦。",["system","hr","executive"]],
 ["wrong-chair","紅酒被請坐主位，因為名牌少了一個字。","會議室主位擺了Wine，紅酒以為要報系統，坐下才發現桌上是一份營運簡報。你看門口真正的翅膀快到了，紅酒問能不能趁現在先批准自己的休假。","這張椅子是借錯的，工作倒是很會留下來。","換正確名牌，讓技術報告回到原議程。","紅酒把椅子交回去，保住自己的工程師身分與沒有亂簽名的一天。","請他先主持，老闆來了再說。","紅酒第一題就被問公司何時上市，系統報告在他手上逐漸變薄。","替主位裝名字辨識器，輸入紅酒只會吐出一張準時下班券。","辨識器是你用紙摺的，紅酒卻很認真問券能不能兌現。","幹，名牌放錯就換，別叫工程師先代演老闆。議程都不一樣，是要他臨場把公司修上市？","靠北，開會先對名字，別再讓紅酒因為一個字母多背一份營運責任。",[],"meeting"]
];
export const WINE_EVENTS_V74=Object.freeze(rows.map(row=>castSceneV74('wine',row)));
